head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00110";
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — formKey, keyValue, returnKey

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "iframe_8", attr: "src", fn: function () { return "/submission/searchDisclosureDocument.do?method=srchSubmitDocRumor&tgtIsurCd=" + String(String((dma_pageContext.get("tgtIsurCd") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00110' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00110' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00110' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00110.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkIt
 * @description check It 처리
 * @param {*} acpt_no acpt_no
 * @param {*} discls_publ_dt discls_publ_dt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIt = async function (acpt_no, discls_publ_dt) {
    let str = "";
    str += "acpt_no : " + acpt_no + "\n";
    str += "discls_publ_dt : " + discls_publ_dt + "\n";
    try {
        const code = (acpt_no == null || acpt_no === "") ? "-" : acpt_no;
        const name = (discls_publ_dt == null || discls_publ_dt === "") ? "-" : discls_publ_dt;
        scwin.frame.fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name);
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00110' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name noSelected
 * @description no Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.noSelected = function () {
    scwin.frame.fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), '-', '-');
    $c.win.closePopup();
};

/**
 * @method
 * @name disclsviewer
 * @description disclsviewer 처리
 * @param {*} _acptno _acptno
 * @returns {void}
 * @hidden N
 */
scwin.disclsviewer = function (_acptno) {
    scwin.frame.fn_Disclsviewer(_acptno);
};
